#include <bits/stdc++.h>
using namespace std;

const int mod = 1000000007;
const int LIM = (1 << 20) - 1;

int n, lim, ans;
int a[10][10], h[10][10][10];
int p1[(1 << 20) + 5], p2[(1 << 20) + 5];
bool flag[10][10];

struct State {
    int mask, P, x, y;
};

int fpow(int x, int y) {
    int res = 1;
    while (y) {
        if (y & 1) res = 1LL * res * x % mod;
        x = 1LL * x * x % mod;
        y >>= 1;
    }
    return res;
}

int inv(int x) {
    return fpow(x, mod - 2);
}

bool checkTriple(int x, int y, int z) {
    int v[3] = {x, y, z};
    int p[3] = {0, 1, 2};
    do {
        if (flag[v[p[0]]][1] && flag[v[p[1]]][2] && flag[v[p[2]]][3]) return true;
    } while (next_permutation(p, p + 3));
    return false;
}

void setFlagMask(int mask) {
    for (int x = 1; x <= 6; ++x)
        for (int y = 1; y <= 3; ++y) {
            int id = (x - 1) * 3 + (y - 1);
            flag[x][y] = (mask >> id) & 1;
        }
}

void finishFirst(int P) {
    int sta = 0;
    for (int i = 1; i <= 6; ++i)
        for (int j = i + 1; j <= 6; ++j)
            for (int k = j + 1; k <= 6; ++k)
                if (checkTriple(i, j, k)) {
                    int x = 1;
                    while (x == i || x == j || x == k) ++x;
                    int y = x + 1;
                    while (y == i || y == j || y == k) ++y;
                    int z = y + 1;
                    while (z == i || z == j || z == k) ++z;
                    sta |= h[x][y][z];
                }
    p1[sta] = (p1[sta] + P) % mod;
}

void finishSecond(int P) {
    int sta = 0;
    for (int i = 1; i <= 6; ++i)
        for (int j = i + 1; j <= 6; ++j)
            for (int k = j + 1; k <= 6; ++k)
                if (checkTriple(i, j, k)) sta |= h[i][j][k];
    p2[sta] = (p2[sta] + P) % mod;
    ans = (ans + 1LL * p1[lim ^ sta] * P) % mod;
}

void runPhase(int phase) {
    vector<State> st;
    st.push_back({0, 1, 1, phase ? 4 : 1});

    while (!st.empty()) {
        State cur = st.back();
        st.pop_back();

        if (cur.x == 7) {
            setFlagMask(cur.mask);
            if (cur.y == 1) finishFirst(cur.P);
            else finishSecond(cur.P);
            continue;
        }

        int col = cur.y <= 3 ? cur.y : cur.y - 3;
        int id = (cur.x - 1) * 3 + (col - 1);
        int nx = (cur.y == 3 || cur.y == 6) ? cur.x + 1 : cur.x;
        int ny;
        if (cur.y == 3) ny = 1;
        else if (cur.y == 6) ny = 4;
        else ny = cur.y + 1;

        int selected = 1LL * cur.P * a[cur.x][cur.y] % mod;
        int skipped = 1LL * cur.P * (mod + 1 - a[cur.x][cur.y]) % mod;

        st.push_back({cur.mask, skipped, nx, ny});
        st.push_back({cur.mask | (1 << id), selected, nx, ny});
    }
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            scanf("%d", &a[i][j]);
            a[i][j] = 1LL * a[i][j] * inv(100) % mod;
        }
    for (int i = n + 1; i <= 6; ++i) a[i][i] = 1;

    int tot = 0;
    for (int i = 1; i <= 6; ++i)
        for (int j = i + 1; j <= 6; ++j)
            for (int k = j + 1; k <= 6; ++k)
                h[i][j][k] = 1 << tot++;

    lim = LIM;

    runPhase(0);

    for (int i = 0; i < 20; ++i)
        for (int mask = 0; mask <= lim; ++mask)
            if ((mask >> i) & 1) {
                p1[mask] += p1[mask ^ (1 << i)];
                if (p1[mask] >= mod) p1[mask] -= mod;
            }

    runPhase(1);

    ans = (mod + 1 - ans) % mod;
    printf("%d\n", ans);
    return 0;
}
